{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Brigatinib, which shares the aniline-pyrimidine core, methoxy substituent, and basic amine side chain with the query, has an absolute oral bioavailability of 46% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Deucravacitinib, a heteroaromatic kinase inhibitor with an aniline-amide and azine core, shows 99% absolute oral bioavailability in healthy subjects, demonstrating that this chemotype can be almost completely absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Brepocitinib, an aminopyrimidine-containing kinase inhibitor, has an estimated absolute bioavailability of 75% in humans, supporting high oral absorption for the query's pyrimidine-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "R406, a methoxy-substituted aminopyrimidine kinase inhibitor, has an absolute oral bioavailability of 54.6% in humans, directly supporting a high F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "ZL-2201, a fused heteroaromatic aminopyrimidine, is predicted to have approximately 70% oral bioavailability in humans at low dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Silodosin, a drug with basic amine and aromatic ether/amide features, has an absolute bioavailability of 32.2% in fasted healthy men, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Isradipine, a lipophilic ester-containing drug, has systemic availability of about 17% in healthy volunteers, providing a contradictory example where first-pass metabolism lowers F below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Nilotinib at a 400 mg dose in fasted healthy volunteers has a predicted bioavailability of 16.0%, showing that solubility-limited absorption can reduce F below 20% in some kinase inhibitors.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a kinase-inhibitor-like heteroaromatic amine with an aniline-pyrimidine core, methoxy group, and basic side chain. Multiple close analogues with high assay-transfer scores show absolute oral bioavailability well above 20% (46–99%), while the few sub-20% examples come from different chemotypes or dose/solubility-limited situations and are outweighed. Therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "The isopropyl ester and acrylamide warhead may introduce metabolic instability not fully captured by the analogue set.",
    "Dose-dependent solubility or absorption effects for the query have not been assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

